"""Complete small examples. Values are illustrative unless explicitly course-derived."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Example:
    inputs: str
    steps: tuple[str, ...]
    result: str
    check: str
    boundary: str
    origin: str = 'Составленный учебный пример; не экспериментальный результат курса.'

    def markdown(self) -> str:
        return '\n\n'.join((f'*Происхождение:* {self.origin}',
            '**Исходные данные.** ' + self.inputs,
            '\n'.join(f'{i}. {s}' for i, s in enumerate(self.steps, 1)),
            '**Результат.** ' + self.result, '**Проверка.** ' + self.check,
            '**Граница применимости.** ' + self.boundary))


def e(inputs, steps, result, check, boundary, origin=None):
    return Example(inputs, tuple(steps), result, check, boundary, *([origin] if origin else []))


